let result = (f tl) in
let new_max = (max result.1 hd) in
let new_cnt = (if (> hd result.1) then 1
else + result.2 (if (== hd result.1) then 1
else 0)) in
{new_max, new_cnt}
end
) xs).2;
cat = fix (
